import { SCORE_THRESHOLDS } from './constants';
import type { ScoreColor } from '@/types';

export function getScoreColor(score: number | null | undefined): ScoreColor {
  if (score == null) return 'gray';
  if (score <= SCORE_THRESHOLDS.red) return 'red';
  if (score <= SCORE_THRESHOLDS.yellow) return 'yellow';
  return 'green';
}

export function getScoreColorClass(score: number | null | undefined): string {
  const color = getScoreColor(score);
  const map: Record<ScoreColor, string> = { red: 'text-red-500', yellow: 'text-yellow-500', green: 'text-green-500', gray: 'text-zinc-500' };
  return map[color];
}

