export async function getDashboardStats() {
  const now = new Date();
  const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
  const yesterdayStart = new Date(todayStart.getTime() - 24 * 60 * 60 * 1000);

  const [total, newToday, contacted, won, totalWeekAgo, newYesterday, contactedWeekAgo, wonWeekAgo] = await Promise.all([
    prisma.lead.count(),
    prisma.lead.count({ where: { createdAt: { gte: todayStart } } }),
    prisma.lead.count({ where: { status: 'CONTACTED' } }),
    prisma.lead.count({ where: { status: 'WON' } }),
    prisma.lead.count({ where: { createdAt: { lt: weekAgo } } }),
    prisma.lead.count({ where: { createdAt: { gte: yesterdayStart, lt: todayStart } } }),
    prisma.lead.count({ where: { status: 'CONTACTED', updatedAt: { lt: weekAgo } } }),
    prisma.lead.count({ where: { status: 'WON', updatedAt: { lt: weekAgo } } }),
  ]);

  return {
    total: { value: total, trend: total - totalWeekAgo },
    newToday: { value: newToday, trend: newToday - newYesterday },
    contacted: { value: contacted, trend: contacted - contactedWeekAgo },
    won: { value: won, trend: won - wonWeekAgo },
  };
}

