export async function runScan(cityNames: string[]): Promise<{ scanLogId: string }> {
  const cities = RUHRGEBIET_CITIES.filter(c => cityNames.includes(c.name));
  if (cities.length === 0) throw new Error('Keine gültigen Städte ausgewählt');

  // ScanLog erstellen
  const scanLog = await prisma.scanLog.create({ data: { cities: JSON.stringify(cityNames), status: 'running' } });
  const startTime = Date.now();

  try {
    // Phase 1: OSM Scraping
    const osmResult = await scrapeOSM(cities);
    let allLeads = osmResult.leads;
    let allErrors = osmResult.errors;

    // Phase 2: Google Maps für Städte mit wenig OSM-Ergebnissen (<10)
    const osmCityCounts = new Map<string, number>();
    for (const lead of osmResult.leads) {
      osmCityCounts.set(lead.city, (osmCityCounts.get(lead.city) ?? 0) + 1);
    }
    const lowCities = cities.filter(c => (osmCityCounts.get(c.name) ?? 0) < 10);
    if (lowCities.length > 0) {
      const gmResult = await scrapeGoogleMaps(lowCities[0].name, BUSINESS_CATEGORIES.slice(0, 10));
      allLeads = [...allLeads, ...gmResult.leads];
      allErrors = [...allErrors, ...gmResult.errors];
    }

    // Phase 3: In DB speichern (upsert, Duplikat-Schutz)
    let newCount = 0, updateCount = 0;
    for (const lead of allLeads) {
      const result = await prisma.lead.upsert({
        where: { name_address_city: { name: lead.name, address: lead.address, city: lead.city } },
        create: { ...lead, source: lead.source as LeadSource },
        update: { phone: lead.phone, website: lead.website, email: lead.email },
      });
      // Wenn createdAt === updatedAt (±1s) → neu, sonst update
      if (Math.abs(result.createdAt.getTime() - result.updatedAt.getTime()) < 1000) newCount++;
      else updateCount++;
    }

    // ScanLog updaten
    await prisma.scanLog.update({
      where: { id: scanLog.id },
      data: { status: 'completed', newLeads: newCount, updatedLeads: updateCount, errors: allErrors.length, duration: Math.round((Date.now() - startTime) / 1000), completedAt: new Date() }
    });
    return { scanLogId: scanLog.id };
  } catch (error) {
    await prisma.scanLog.update({ where: { id: scanLog.id }, data: { status: 'failed', errors: 1, duration: Math.round((Date.now() - startTime) / 1000), completedAt: new Date() } });
    throw error;
  }
}

