export async function analyzeWebsite(leadId: string): Promise<WebsiteAnalysis> {
  const lead = await prisma.lead.findUnique({ where: { id: leadId } });
  if (!lead) throw new Error('Lead nicht gefunden');
  if (!lead.website) throw new Error('Lead hat keine Website');

  const url = lead.website.startsWith('http') ? lead.website : `https://${lead.website}`;

  // HTML einmal laden für alle Analyzer die es brauchen
  let html = '';
  let headers = new Headers();
  try {
    const res = await fetch(url, { signal: AbortSignal.timeout(15000), headers: { 'User-Agent': 'Mozilla/5.0 (compatible; FPZBot/1.0)' } });
    html = await res.text();
    headers = res.headers;
  } catch (err) {
    console.error('HTML fetch failed:', err);
  }

  // Alle Analyzer parallel
  const [perfResult, seoResult, secResult, techResult, designResult, ageResult, contentResult] = await Promise.allSettled([
    analyzePerformance(url),
    analyzeSEO(url),
    analyzeSecurity(url),
    analyzeTechStack(url, html),
    analyzeDesign(url, html),
    analyzeAge(url, html),
    analyzeContent(url, html),
  ]);

  // Scores extrahieren (0 bei Fehler)
  const getScore = (result: PromiseSettledResult<AnalysisResult>, key?: string) =>
    result.status === 'fulfilled' ? (key ? (result.value as Record<string, unknown>)[key] as number : result.value.score) : 0;

  const perf = perfResult.status === 'fulfilled' ? perfResult.value : null;
  const scores = {
    performanceScore: perf?.performanceScore ?? 0,
    seoScore: Math.round(((getScore(seoResult) + (perf?.seoScore ?? 0)) / (perf ? 2 : 1))),
    mobileScore: perf?.accessibilityScore ?? getScore(designResult),
    securityScore: getScore(secResult),
    designScore: getScore(designResult),
    techScore: getScore(techResult),
    ageScore: getScore(ageResult),
    accessibilityScore: perf?.accessibilityScore ?? 0,
    contentScore: getScore(contentResult),
  };

  const overallScore = calculateOverallScore({
    performance: scores.performanceScore,
    seo: scores.seoScore,
    mobile: scores.mobileScore,
    security: scores.securityScore,
    design: scores.designScore,
    tech: scores.techScore,
    age: scores.ageScore,
    accessibility: scores.accessibilityScore,
    content: scores.contentScore,
  });

  // Alle Details sammeln
  const allDetails = {
    performance: perfResult.status === 'fulfilled' ? perfResult.value : { error: String(perfResult.reason) },
    seo: seoResult.status === 'fulfilled' ? seoResult.value.details : { error: String(seoResult.reason) },
    security: secResult.status === 'fulfilled' ? secResult.value.details : { error: String(secResult.reason) },
    techStack: techResult.status === 'fulfilled' ? techResult.value.details : { error: String(techResult.reason) },
    design: designResult.status === 'fulfilled' ? designResult.value.details : { error: String(designResult.reason) },
    age: ageResult.status === 'fulfilled' ? ageResult.value.details : { error: String(ageResult.reason) },
    content: contentResult.status === 'fulfilled' ? contentResult.value.details : { error: String(contentResult.reason) },
  };

  // In DB speichern (upsert)
  const analysis = await prisma.websiteAnalysis.upsert({
    where: { leadId },
    create: { leadId, ...scores, overallScore, details: JSON.stringify(allDetails), techStack: techResult.status === 'fulfilled' ? JSON.stringify(techResult.value.details) : null },
    update: { ...scores, overallScore, details: JSON.stringify(allDetails), techStack: techResult.status === 'fulfilled' ? JSON.stringify(techResult.value.details) : null, analyzedAt: new Date() },
  });

  // Lead overallScore updaten
  await prisma.lead.update({ where: { id: leadId }, data: { overallScore } });

  return analysis;
}

