import Groq from 'groq-sdk';

export class RateLimitError extends Error { constructor(message: string) { super(message); this.name = 'RateLimitError'; } }

export async function generateWithGroq(prompt: string, systemPrompt: string): Promise<string> {
  const apiKey = process.env.GROQ_API_KEY;
  if (!apiKey || apiKey === 'gsk_your_key_here') throw new Error('GROQ_API_KEY nicht konfiguriert');

  const groq = new Groq({ apiKey });

  try {
    const completion = await groq.chat.completions.create({
      model: 'llama-3.3-70b-versatile',
      messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: prompt }],
      temperature: 0.3,
      max_tokens: 2000,
    });
    return completion.choices[0]?.message?.content ?? '';
  } catch (error: unknown) {
    if (error instanceof Error && 'status' in error && (error as { status: number }).status === 429) {
      throw new RateLimitError('Groq Rate Limit erreicht');
    }
    throw error;
  }
}

