export async function generateWithHuggingFace(prompt: string, systemPrompt: string): Promise<string> {
  const token = process.env.HUGGINGFACE_TOKEN;
  if (!token || token === 'hf_your_token_here') throw new Error('HUGGINGFACE_TOKEN nicht konfiguriert');

  const response = await fetch('https://api-inference.huggingface.co/models/mistralai/Mixtral-8x7B-Instruct-v0.1', {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ inputs: `<s>[INST] ${systemPrompt}\n\n${prompt} [/INST]`, parameters: { max_new_tokens: 2000, temperature: 0.3 } }),
    signal: AbortSignal.timeout(30000),
  });

  if (!response.ok) throw new Error(`HuggingFace Error: ${response.status} ${response.statusText}`);
  const result = await response.json();
  return Array.isArray(result) ? result[0]?.generated_text ?? '' : result?.generated_text ?? '';
}

