import { generateWithGroq, RateLimitError } from './groq';
import { generateWithHuggingFace } from './huggingface';

export async function generateText(prompt: string, systemPrompt: string): Promise<string> {
  // Versuch 1: Groq
  try { return await generateWithGroq(prompt, systemPrompt); }
  catch (error) {
    if (!(error instanceof RateLimitError)) throw error;
    console.warn('Groq Rate Limited, Fallback auf HuggingFace...');
  }

  // Versuch 2: HuggingFace
  await new Promise(r => setTimeout(r, 1000));
  try { return await generateWithHuggingFace(prompt, systemPrompt); }
  catch (hfError) { console.warn('HuggingFace fehlgeschlagen, letzter Versuch Groq...'); }

  // Versuch 3: Groq Retry
  await new Promise(r => setTimeout(r, 2000));
  return await generateWithGroq(prompt, systemPrompt);
}

